#!/usr/bin/env node
/** Concatenates the engine and the bot into the installable userscript. */
const fs = require("fs");
const path = require("path");
const root = path.join(__dirname, "..");
const read = (p) => fs.readFileSync(path.join(root, p), "utf8");

const header = `// ==UserScript==
// @name         BC Club Cards Bot
// @namespace    https://github.com/Nicole-bc/BC_Clubcardsbot
// @version      ${require(path.join(root, "package.json")).version}
// @description  Builds a Club Cards deck from your unlocked pool and plays it.
// @match        https://*.bondageprojects.elementfx.com/*
// @match        https://*.bondage-europe.com/*
// @match        https://*.bondageprojects.com/*
// @grant        none
// @run-at       document-idle
// ==/UserScript==

// Generated by tools/bundle.js — edit src/deck-engine.js and src/bot.js instead.
`;

const out = [header, read("src/deck-engine.js"), read("src/bot.js")].join("\n");
fs.mkdirSync(path.join(root, "dist"), { recursive: true });
fs.writeFileSync(path.join(root, "dist", "bc-clubcards-bot.user.js"), out);
console.log(`dist/bc-clubcards-bot.user.js  (${(out.length / 1024).toFixed(1)} KB)`);
